public class Singleton {
   //1 、私有构造⽅法 : 外界⽆法使⽤构造⽅法来创建本类的实例对象
    private Singleton(){}

    //2 、声明⼀个成员变量   注意  volatile 是为了防⽌指令重排序导致对象未初始化就被使⽤
    private static volatile Singleton instance;

    //4 、提供⼀个获取单例的⼊⼝，注意是  public 和  static
    public static Singleton getInstance(){
        // 第⼀次检查 : 如果 instance 不为 null, 不需要抢占锁 , 可以直接返回对象
        if(instance == null){
            // 如果为 null, 说明⾸次访问需要创建实例对象，使⽤ synchronized 同步代码
块
            // 锁对象 : 当前类的字节码对象
            synchronized (Singleton.class){
                // 某个线程抢到锁之后 , 需要再次判断 instance 是否为 null, 保证单例安全
                if(instance == null){
                    instance = new Singleton();
                }
            }
        }
        return instance;
    }
}
